function tone(freq=520,duration=.1,type='sine',volume=.08,category='effects'){if(!audio||!soundOn)return;const o=audio.createOscillator(),g=audio.createGain();o.type=type;o.frequency.value=freq;o.connect(g);g.connect(audioMixer.output(category)||audio.destination);o.onended=()=>{o.disconnect();g.disconnect();};g.gain.setValueAtTime(volume,audio.currentTime);g.gain.exponentialRampToValueAtTime(.001,audio.currentTime+duration);o.start();o.stop(audio.currentTime+duration);}
function cue(kind){if(kind==='sabotage'){[220,165,220].forEach((n,i)=>setTimeout(()=>tone(n,.18,'triangle',.025),i*220));}else if(kind==='repair'){[440,660,880].forEach((n,i)=>setTimeout(()=>tone(n,.12,'triangle',.025),i*95));}else if(kind==='impostor-reveal'){tone(82,.8,'sawtooth',.035);setTimeout(()=>tone(123,.5,'triangle',.045),170);}else if(kind==='meeting'){tone(460,.18,'triangle');setTimeout(()=>tone(690,.3,'triangle'),220);}else if(kind==='death'){tone(160,.5,'sawtooth',.06);}else if(kind==='win'){[440,554,660,880].forEach((n,i)=>setTimeout(()=>tone(n,.2),i*130));}else if(kind==='task'){tone(700,.12);setTimeout(()=>tone(950,.16),150);}else if(kind==='lose'){[330,294,220,165].forEach((n,i)=>setTimeout(()=>tone(n,.24,'triangle',.045),i*140));}else if(kind==='stairs'){tone(330,.12,'triangle',.04);setTimeout(()=>tone(475,.2,'triangle',.04),130);}else if(kind==='reveal'){tone(390,.25,'sine',.055);setTimeout(()=>tone(590,.3,'triangle',.045),260);}else tone(500,.08);}
