async function request(path,body){const start=Date.now();const res=await fetch(path,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(body),cache:'no-store',signal:AbortSignal.timeout(7000)});let data;try{data=await res.json();}catch{throw new Error('El servidor no ha respondido correctamente.');}if(!res.ok){const error=new Error(data.error||'No se ha podido completar la acción.');error.status=res.status;throw error;}if(data.state){const end=Date.now(),rtt=end-start,sample=data.state.serverTime-(start+end)/2;if(!clockReady||rtt<=clockRtt*1.15+10){clockOffset=clockReady?clockOffset+(sample-clockOffset)*.08:sample;clockReady=true;}clockRtt=Math.min(clockRtt,rtt);}return data;}
async function enter(create){enableAudio();updateAppearance();$('menuError').textContent='';$('createBtn').disabled=true;$('joinBtn').disabled=true;
  try{const r=await request(create?'/api/create':'/api/join',{profile:{...appearance,introProtocol:1},code:$('roomInput').value.toUpperCase()});session=r.session;sessionStorage.setItem('sanagus.session',JSON.stringify(session));accept(r.state);nextPulse=0;cue();$('world').focus();}catch(e){$('menuError').textContent=e.message;}finally{$('createBtn').disabled=false;$('joinBtn').disabled=false;}}
$('createBtn').addEventListener('click',()=>enter(true));$('joinForm').addEventListener('submit',e=>{e.preventDefault();enter(false);});$('roomInput').addEventListener('input',()=>{$('roomInput').value=$('roomInput').value.toUpperCase().replace(/[^A-Z2-9]/g,'');});
let openRoomList=[],roomsPage=0;
function renderOpenRooms(){const pageSize=2,total=Math.max(1,Math.ceil(openRoomList.length/pageSize));roomsPage=Math.min(roomsPage,total-1);$('roomsList').innerHTML=openRoomList.slice(roomsPage*pageSize,(roomsPage+1)*pageSize).map(r=>`<button class="room-entry" data-room="${esc(r.code)}"><span><b>${esc(r.host)}</b><small>CÓDIGO ${esc(r.code)} · ${r.impostors} IMPOSTOR${r.impostors===1?'':'ES'}</small></span><strong>${r.players} / ${r.maxPlayers} →</strong></button>`).join('');$('roomsPage').textContent=`${roomsPage+1} / ${total}`;$('prevRooms').disabled=roomsPage===0;$('nextRooms').disabled=roomsPage===total-1;}
async function refreshRooms(){if($('openRooms').hidden)return;try{const res=await fetch('/api/rooms',{cache:'no-store',signal:AbortSignal.timeout(7000)}),data=await res.json();if(!res.ok)throw new Error(data.error||'No se pudieron cargar las salas.');openRoomList=data.rooms;$('roomsStatus').textContent=data.rooms.length?`${data.rooms.length} salas disponibles`:'No hay salas abiertas ahora. Puedes crear una.';renderOpenRooms();}catch(e){$('roomsStatus').textContent=e.message;}}
