 const vent=ready&&now()>=s.me.ventReady&&(s.me.role==='impostor'||s.me.specialRole==='engineer')?VENTS.find(v=>near(v,75)&&(s.config.floors==='both'||v.links.some(id=>VENTS.some(q=>q.id===id&&q.floor===v.floor)))):null;
 const console=worldFor(s).CAMERA_CONSOLE,camera=ready&&console&&near(console,150);const meetingFloor=s.config.floors==='1'?1:0,emergency=ready&&s.me.emergencies>0&&s.me.floor===meetingFloor&&roomAt(local.x,local.y,meetingFloor)===(s.config.map==='club'?'Escenario principal':meetingFloor?'Sala de profesores':'Recepción')&&distance(local,FLOORS[meetingFloor].emergency)<=190;
