async function openCameras(){if(!state||!options().camera)return;try{await act('camera',{id:'all'});if(!state.cameraFeeds?.length)return;openModal('Seguridad · Videovigilancia',`<div class="camera-wall"><canvas id="cameraCanvas" aria-label="Cuatro cámaras de vigilancia simultáneas en directo"></canvas></div><div class="camera-toolbar"><span><i class="status-dot"></i> 4 CÁMARAS EN DIRECTO</span><button type="button" id="exitCameras" class="secondary">Salir de cámaras</button></div><p class="small-note">Tu personaje permanece en Seguridad. Los sabotajes de equipos cortan la señal.</p>`,'camera');$('exitCameras').addEventListener('click',()=>closeModal());}catch(e){toast(e.message);}}
$('cameraBtn').addEventListener('click',openCameras);
function openModal(title,html,kind='help'){if(modalKind)closeModal(false);if(title==='Cómo jugar'&&state?.config.map==='club'){html=html.replace('entre seis averías','entre nueve averías').replaceAll('Empollón','Camarero').replaceAll('Delegado','Portero').replaceAll('El enchufe','DJ').replaceAll('Copiador Boss','Dueño').replaceAll('entre plantas','entre salas').replaceAll('las plantas elegidas','el club').replaceAll('Junta a tu clase.','Junta a tu equipo.').replace('Los documentos se recogen en el Despacho de Vaquero y se entregan en Dirección.','El personal calibra equipos, prepara bebidas y ordena las pistas.').replace('en Recepción (P0), o en Profesores (P1) si se juega solo allí','en el centro del escenario principal').replace('En dos plantas la emergencia cooperativa','La emergencia cooperativa').replace(/Dos profesores patrullan[\s\S]*?El plano escolar es orientativo y está basado en la plantilla recibida\./,'En la discoteca no hay profesores. Acércate a Seguridad y pulsa Cámaras para vigilar los cuatro pasillos. Los sabotajes de equipos cortan la señal.');}if((kind==='help'||kind==='appearance')&&modalKind)closeModal();modalKind=kind;keys.clear();$('modal').classList.toggle('camera-modal',kind==='camera');$('modal').classList.toggle('interactive-modal',kind==='task'||kind==='repair');$('modalTitle').textContent=title;$('modalContent').classList.remove('operation-success');$('modalContent').innerHTML=html;$('taskError').textContent='';$('modalEyebrow').textContent=kind==='help'?'MANUAL DE LA EXPEDICIÓN':kind==='appearance'?'IDENTIDAD DEL EXPLORADOR':'ESTACIÓN DE TRABAJO';show('modal',true);}
function closeModal(cancel=true){if(modalKind==='computer')restoreRoomComputer();const wasCamera=modalKind==='camera';if(wasCamera&&state?.phase==='game')fire('exitCamera');if(modalKind==='appearance')wardrobeAbort.abort();if(taskCleanup){taskCleanup();taskCleanup=null;}const wasTask=modalKind==='task'||modalKind==='repair';taskTimers.forEach(clearTimeout);taskTimers=[];activeTask=null;modalKind=null;show('modal',false);show('ventDock',false);if(state&&['lobby','game','meeting'].includes(state.phase))$(state.phase==='meeting'?'meetingCards':'world').focus({preventScroll:true});if(cancel&&wasTask&&session)fire('cancel');}
$('closeModal').addEventListener('click',()=>closeModal());
$('helpBtn').addEventListener('click',()=>openModal('Cómo jugar',`<div class="help-list"><div><b>Junta a tu clase.</b> Crea una sala y comparte el código. Mínimo 4 personas para un impostor, 7 para dos. El líder configura y empieza.</div><div><b>Explora las plantas elegidas.</b> WASD o flechas. E para tareas, botón rojo, reparación y escaleras. M abre el plano con pestañas de planta. Cada tarea indica su ubicación.</div><div><b>Tripulantes.</b> Completad las tareas o expulsad a todos los impostores. Los documentos se recogen en el Despacho de Vaquero y se entregan en Dirección. Los espectros pueden atravesar paredes y seguir trabajando.</div><div><b>Impostores.</b> Q elimina a un tripulante cercano después de la recarga que configure el líder. V abre una rejilla cercana: entra, viaja entre las tres rejillas de tu circuito y sale donde elijas. No hay conexiones entre los cuatro circuitos. No puedes matar ni moverte mientras estás oculto. El ingeniero también puede usarlas.</div><div><b>Roles adicionales.</b> Empollón: N abre una libreta privada incluso durante reuniones. Ingeniero: V permite viajar por alcantarillas entre plantas. Delegado: selecciona a alguien y usa el pulgar decisivo una vez; acertar gana y fallar te expulsa. El enchufe: conoce el nombre y planta de cada muerte. Creyente: recibe señales de cuatro emojis de los fantasmas; al morir, estos usan 1–4 en la barra inferior. Los roles son únicos y a veces no se asigna ninguno. Impostor Fantasma: F lo oculta 15 s. Copiador Boss: F copia a otro vivo 30 s. F termina el efecto; ambos se recargan 90 s.</div><div><b>Reuniones.</b> R denuncia un cadáver cercano. El botón rojo está en Recepción (P0), o en Profesores (P1) si se juega solo allí; cada jugador dispone de una reunión. La tableta muestra a todo el equipo y pausa el movimiento. Abre el chat para debatir. Selecciona una tarjeta, confirma con ✓ o cancela con ×. SKIP permite abstenerte. Empate y omitir no expulsan. Los votos sin emitir al agotarse el tiempo cuentan como omitidos. Todos los votos son anónimos.</div><div><b>Sabotajes.</b> El botón ⚡ permite elegir entre seis averías. Se reparan en los paneles de las plantas activas. En dos plantas la emergencia cooperativa requiere dos personas en paneles distintos, con menos de 8 s de diferencia. Las puertas se abren a los 18 s; el sabotaje sigue activo hasta reparar los paneles. Si pasan 90 s sin reparar, gana el impostor. La recarga es de 112,5 s.</div><div><b>Conexión.</b> Recargar recupera tu sesión. Si pierdes conexión durante la partida, tu plaza se conserva; en la espera caduca tras 30 s. Dos profesores patrullan cada partida. En los pasillos te persiguen y, si te alcanzan, te retienen 30 s en Expulsados; entrar en un aula te protege. El plano escolar es orientativo y está basado en la plantilla recibida.</div></div>`));
$('editAppearance').addEventListener('click',()=>{const p=state.me;openModal('Armario de la caravana',`<div class="wardrobe-preview">${robotSVG(p)}</div><label class="field-label" for="editName">Nombre</label><input id="editName" maxlength="18" value="${esc(p.name)}"><label class="field-label" for="editColor">Color de identidad</label><select id="editColor">${COLOR_NAMES.map((n,i)=>`<option value="${i}" ${i===p.color?'selected':''} ${state.roster.some(q=>q.id!==p.id&&q.color===i)?'disabled':''}>${n}</option>`).join('')}</select><nav class="wardrobe-tabs" aria-label="Secciones del vestuario"><button type="button" data-wardrobe-tab="clothes" class="selected" aria-pressed="true">Ropa</button><button type="button" data-wardrobe-tab="face" aria-pressed="false">Personaje</button><button type="button" data-wardrobe-tab="extras" aria-pressed="false">Accesorios</button></nav><div class="wardrobe-fields">${Object.entries(wardrobe).map(([id,choices])=>`<label data-wardrobe-group="${wardrobeSection(id)}" ${wardrobeSection(id)==='clothes'?'':'hidden'}>${wardrobeLabels[id]}<select data-wardrobe="${id}">${choices.map((n,i)=>`<option value="${i}" ${i===(p[id]??0)?'selected':''}>${esc(n)}</option>`).join('')}</select></label>`).join('')}</div><button id="saveAppearance" class="primary wide">Guardar ropa →</button>`,'appearance');
 $('modalContent').querySelector('.wardrobe-tabs').addEventListener('click',e=>{const b=e.target.closest('[data-wardrobe-tab]');if(!b)return;$('modalContent').querySelectorAll('[data-wardrobe-tab]').forEach(t=>{const chosen=t===b;t.classList.toggle('selected',chosen);t.setAttribute('aria-pressed',String(chosen));});$('modalContent').querySelectorAll('[data-wardrobe-group]').forEach(label=>label.hidden=label.dataset.wardrobeGroup!==b.dataset.wardrobeTab);});
 const read=()=>{const result={name:$('editName').value,color:Number($('editColor').value)};document.querySelectorAll('[data-wardrobe]').forEach(el=>result[el.dataset.wardrobe]=Number(el.value));return result;};
 let appearanceTimer=0;const signal=wardrobeSignal();signal.addEventListener('abort',()=>clearTimeout(appearanceTimer),{once:true});
 $('modalContent').addEventListener('input',()=>{const p=read();$('modalContent').querySelector('.wardrobe-preview').innerHTML=robotSVG(p);tone(600,.035,'triangle',.015);clearTimeout(appearanceTimer);appearanceTimer=setTimeout(()=>{if(modalKind==='appearance'&&p.name.trim().length>=2)act('profile',p).catch(e=>{if(modalKind==='appearance')$('taskError').textContent=e.message;});},250);},{signal});
 $('saveAppearance').addEventListener('click',async()=>{const p=read();try{await act('profile',p);appearance=p;$('playerName').value=p.name;for(const id of Object.keys(wardrobe))$(id).value=p[id];updateAppearance();closeModal(false);}catch(e){$('taskError').textContent=e.message;}});
});
