for(const node of roomComputerParts)node.classList.add('computer-control');
const computerStash=document.createElement('div');computerStash.hidden=true;computerStash.id='computerStash';roomComputerHome.append(computerStash);roomComputerParts.forEach(n=>computerStash.append(n));
$('editAppearance').hidden=true;roomComputerHome.querySelector('.settings-title').hidden=true;
const departure=document.createElement('button');departure.type='button';departure.id='departureBtn';departure.className='primary wide';departure.textContent='Salir de viaje →';departure.addEventListener('click',()=>fire('start'));roomComputerHome.append(departure);
const lobbyHint=document.createElement('p');lobbyHint.className='small-note';lobbyHint.textContent='Acércate al armario para cambiarte o al ordenador para consultar los ajustes. Pulsa E / Usar.';roomComputerHome.append(lobbyHint);
function restoreRoomComputer(){roomComputerParts.forEach(n=>computerStash.append(n));}
function openRoomComputer(){openModal('Ordenador de la caravana','<div class="room-monitor"><div class="monitor-top"><i></i> SANAGUS / CONTROL DE VIAJE</div><p class="small-note">'+(state.host===state.me.id?'Eres el líder: puedes configurar la salida.':'Consulta los ajustes. Solo el líder puede cambiarlos.')+'</p><div id="roomComputerSettings"></div></div>','computer');roomComputerParts.forEach(n=>$('roomComputerSettings').append(n));const bots=document.createElement('section');bots.className='bot-controls';bots.innerHTML='<h3>TRIPULACIÓN AUTOMÁTICA</h3><p>Los bots recorren tareas, reparan, reportan y votan. Los impostores buscan víctimas y sabotean.</p><div><button type="button" class="secondary" data-bot="addBot">+ Añadir bot</button><button type="button" class="secondary" data-bot="removeBot">− Eliminar bot</button><button type="button" class="secondary" data-bot="fillBots">Rellenar plazas</button></div><output id="botStatus"></output>';bots.addEventListener('click',async e=>{const b=e.target.closest('[data-bot]');if(!b||b.disabled)return;b.disabled=true;try{await act(b.dataset.bot);tone(650,.12,'triangle',.025);}catch(error){$('taskError').textContent=error.message;}finally{syncSettings();}});$('roomComputerSettings').append(bots);syncSettings();}
function wardrobeSignal(){wardrobeAbort.abort();wardrobeAbort=new AbortController();return wardrobeAbort.signal;}
document.addEventListener('keydown',e=>{const k=e.key.toLowerCase(),typing=['INPUT','TEXTAREA','SELECT'].includes(document.activeElement?.tagName);if(k==='escape'&&!$('notebookOverlay').hidden){e.preventDefault();show('notebookOverlay',false);$(state?.phase==='meeting'?'meetingCards':'world').focus();return;}if(typing)return;if(['arrowup','arrowdown','arrowleft','arrowright',' '].includes(k)&&state)e.preventDefault();if(k==='escape'){if(!$('notebookOverlay').hidden)show('notebookOverlay',false);else if(!$('mapOverlay').hidden)show('mapOverlay',false);else if(modalKind)closeModal();return;}if(k==='n'&&!e.repeat&&state?.me.specialRole==='nerd'){e.preventDefault();toggleNotebook();return;}if(k==='m'&&!e.repeat&&!modalKind){toggleMap();return;}if(!e.repeat&&/^[1-4]$/.test(k)&&state&&!state.me.alive&&!modalKind&&$('mapOverlay').hidden&&$('notebookOverlay').hidden&&state.believerAlive&&now()>=state.me.spiritReady){const emoji=state.spiritEmojis?.[Number(k)-1];if(emoji){e.preventDefault();fire('spirit',{emoji});return;}}keys.add(k);if(!e.repeat&&['w','a','s','d','arrowup','arrowleft','arrowdown','arrowright'].includes(k)){inputDirty=true;nextPulse=0;pump();}if(e.repeat||modalKind||!$('mapOverlay').hidden)return;if(k==='e')use();if(k==='v'&&!$('ventBtn').disabled)$('ventBtn').click();if(k==='f'&&!$('abilityBtn').disabled)$('abilityBtn').click();if(k==='q'&&!$('killBtn').disabled)$('killBtn').click();if(k==='r'&&!$('reportBtn').disabled)$('reportBtn').click();});
document.addEventListener('keyup',e=>{const k=e.key.toLowerCase();keys.delete(k);if(['w','a','s','d','arrowup','arrowleft','arrowdown','arrowright'].includes(k)){inputDirty=true;nextPulse=0;pump();}});window.addEventListener('blur',()=>{touchStick.reset();keys.clear();inputDirty=true;nextPulse=0;pump();});document.addEventListener('visibilitychange',()=>{if(document.hidden){touchStick.reset();keys.clear();inputDirty=true;nextPulse=0;pump();}});

function openTask(task){if(!task)return;openInteractive(task,'task');}
function openRepair(repair){openInteractive(repair,'repair');}
function openInteractive(task,kind){
 if(taskCleanup)taskCleanup();openModal(task.label,'',kind);activeTask=task;
 taskCleanup=mountTask($('modalContent'),task,{tone,submit:async solution=>{
  const delay=Math.max(0,task.start+task.minDuration-now()+100);if(delay)await new Promise(resolve=>{taskTimers.push(setTimeout(resolve,delay));});
  if(activeTask!==task)throw new Error('La tarea se ha cerrado.');
  const result=await act(kind==='task'?'finishTask':'finishRepair',{id:task.id,solution});cue('task');if(activeTask===task&&modalKind){$('modalContent').classList.add('operation-success');const banner=document.createElement('div');banner.className='task-success-banner';banner.innerHTML='<span>✓</span><b>OPERACIÓN COMPLETADA</b>'; $('modalContent').append(banner);await new Promise(resolve=>setTimeout(resolve,650));$('modalContent').classList.remove('operation-success');if(activeTask===task)closeModal(false);}
  toast(result.carrying?'Documentos recogidos. Llévalos a Dirección (P0).':result.retryCoop?'Necesitáis dos personas distintas en los dos paneles.':kind==='task'?'Tarea completada.':state.sabotage?.kind==='emergency'?'Panel confirmado: la otra persona tiene 8 s.':'Panel reparado. Comprueba el otro.');
 }});
}

let introAckBusy=false,introAckAt=0;
function acknowledgeIntro(){if(!state?.intro||document.hidden||introAckBusy||now()-introAckAt<500)return;const i=state.intro,stage=i.stage==='travel'&&now()>=i.travelEnd&&!i.ownArrivalReady?'arrival':['reveal','reading'].includes(i.stage)&&state.me.role&&!i.ownRoleShownAt&&!$('roleOverlay').hidden?'role':null;if(!stage)return;introAckBusy=true;requestAnimationFrame(()=>{if(document.hidden){introAckBusy=false;return;}introAckAt=now();act('introReady',{stage}).catch(e=>toast(e.message)).finally(()=>introAckBusy=false);});}
let skippedJourney=null;
$('skipJourney').addEventListener('click',()=>{skippedJourney=state?.gameNumber;$('journeyCanvas').style.visibility='hidden';show('journeyWait',true);});
function frame(time){acknowledgeIntro();voteCountdown.update(state,now());if(state?.phase==='ended'){const active=now()<state.result.time+4200;show('finaleOverlay',active);if(active){const canvas=$('finaleCanvas'),r=canvas.getBoundingClientRect(),d=Math.min(window.devicePixelRatio||1,1.5);if(canvas.width!==Math.round(r.width*d))canvas.width=Math.max(1,Math.round(r.width*d));if(canvas.height!==Math.round(r.height*d))canvas.height=Math.max(1,Math.round(r.height*d));drawFinale(canvas,state,now(),{reduced:reducedEffects});}}if(state?.phase==='game'&&(state.intro?state.intro.stage==='travel':now()<(state.travelUntil||0))){const canvas=$('journeyCanvas'),r=canvas.getBoundingClientRect(),d=Math.min(window.devicePixelRatio||1,1.5);if(canvas.width!==Math.round(r.width*d))canvas.width=Math.max(1,Math.round(r.width*d));if(canvas.height!==Math.round(r.height*d))canvas.height=Math.max(1,Math.round(r.height*d));if(skippedJourney!==state.gameNumber){canvas.style.visibility='visible';show('journeyWait',!!state.intro&&now()>=state.intro.travelEnd);drawJourney(canvas,state.intro?Math.min(now(),state.intro.travelEnd):now(),state,{reduced:reducedEffects});}}const {LOBBY,MEETING,mapFor}=worldFor(state);updateTouchControls();const dt=Math.min(.05,(time-lastTime)/1000);lastTime=time;if(!state){drawHero($('hero'),time);drawAvatar($('avatar'),appearance,time);}else{const axis=input(),map=state.phase==='meeting'?MEETING:state.phase==='lobby'?LOBBY:mapFor(state.me.floor,state.sabotage),ghost=state.phase!=='lobby'&&!state.me.alive;if(['lobby','game'].includes(state.phase)){const px=local.x,py=local.y;move(state.phase==='game'&&state.me.alive&&state.me.expelledUntil>now()?detentionMap(map):map,local,axis.x,axis.y,dt,ghost,state.config.speed);recordMotion(axis,dt);if((axis.x||axis.y)&&!ghost&&Math.hypot(local.x-px,local.y-py)>.25&&time-lastStep>290){lastStep=time;tone(95+(Math.floor(time/290)%2)*20,.035,'triangle',.013);}}local.input=axis;for(const p of [...state.players,...(state.teachers||[])]){if(p.id===state.me.id)continue;const at=remoteAt(remoteSamples.get(p.id),now(),p.detained?detentionMap(map):map,state.config.speed);if(at)rendered.set(p.id,at);}for(const id of rendered.keys())if(!remoteSamples.has(id))rendered.delete(id);if(state.phase!=='meeting')drawWorld($('world'),state,local,rendered,cam,dt,time);if(!$('mapOverlay').hidden&&time-lastUi>100){drawMiniMap($('mapCanvas'),state,local,mapFloor);updateMapFloorButtons();}if(time-lastUi>100){lastUi=time;updateClocks();}}
  if(modalKind==='camera'&&state?.cameraFeed&&$('cameraCanvas')){drawCamera($('cameraCanvas'),state,rendered,time);}
  requestAnimationFrame(frame);
}
requestAnimationFrame(frame);
try{session=JSON.parse(sessionStorage.getItem('sanagus.session')||'null');}catch{}if(session){setSceneMode('game');show('appHeader',false);show('menu',false);show('game',true);show('networkBanner',true);$('networkBanner').textContent='Recuperando tu sesión… Puedes pulsar Salir para volver al menú.';$('roomCode').textContent=session.code;nextPulse=0;pump();}
